from pathlib import Path
p=Path('output/ui-v4/src/StarterPlayer/StarterPlayerScripts/ExpeditionClient.lua')
s=p.read_text(encoding='utf-8').replace('compact and 118 or 74','compact and 206 or 74').replace('"settings",margin,virtualH-60,48','"settings",compact and 0 or margin,virtualH-60,48')
s=s.replace('if res.msg and name ~= "RolarGacha" then','if res.msg and name ~= "RolarGacha" and name ~= "UITravel" then')
p.write_text(s,encoding='utf-8')
p=Path('output/ui-v4/src/ReplicatedStorage/ExpeditionUI/Theme.lua')
s=p.read_text(encoding='utf-8').replace('local index=T.IconIndex[key] or','local index=(key=="summon" and T.IconIndex.units) or T.IconIndex[key] or')
p.write_text(s,encoding='utf-8')
p=Path('output/ui-v4/src/ReplicatedStorage/ExpeditionUI/Inventory.lua')
s=p.read_text(encoding='utf-8')
a=s.index('\tfunction build(p, w, h)');b=s.index('\n\tctx.popup(opts.title',a)
part=s[a:b]
part=part.replace('p, w, h = scrollableSpace(p, "ConsumptionLayout", w, h, 500)','local split = ctx.compact and w >= 620\n\t\tif not split then p, w, h = scrollableSpace(p, "ConsumptionLayout", w, h, 500) end\n\t\tlocal infoW = split and math.floor(w * .42) or w')
part=part.replace('w - 150, 30, 22','infoW - 122, 30, 22').replace('w - 150, 0, 150, 30','infoW - 122, 0, 122, 30').replace('0, 38, w, 24','0, 38, infoW, 24')
part=part.replace('0, 72, w-104, 34','0, 72, split and infoW or w-104, 34')
part=part.replace('local pickCols=w<780 and 3 or 6','local pickCols=split and 3 or (w<780 and 3 or 6)')
part=part.replace('local gridTop = 108 + pickRows*(buttonH+8) + 12','local gridTop = split and 0 or (108 + pickRows*(buttonH+8) + 12)\n\t\tlocal gridX = split and (infoW + 20) or 0\n\t\tlocal gridW = w - gridX')
part=part.replace('0, 108, w, buttonH, 15','0, 108, infoW, split and 100 or buttonH, 15')
part=part.replace('(w - gap * (pickCols-1)) / pickCols','(infoW - gap * (pickCols-1)) / pickCols')
part=part.replace('"Limpar", w-90, 72, 90, 28','"Limpar", split and 0 or w-90, split and (108+pickRows*(buttonH+8)) or 72, split and infoW or 90, split and 36 or 28')
part=part.replace('"Candidates", 0, gridTop, w, gridH','"Candidates", gridX, gridTop, gridW, gridH')
part=part.replace('(w - 8) / 130','(gridW - 8) / 112').replace('(w - 12 - (cols - 1) * gap)','(gridW - 12 - (cols - 1) * gap)').replace('0, 0, w - 12, gridH','0, 0, gridW - 12, gridH')
part=part.replace('0, h - buttonH - 32, w, 26','gridX, h - buttonH - 32, gridW, 26').replace('local actionX, actionW = 0, w','local actionX, actionW = gridX, gridW').replace('actionW = (w - 12) / 2; actionX = actionW + 12','actionW = (gridW - 12) / 2; actionX = gridX + actionW + 12').replace('"Voltar à seleção", 0, h - buttonH','"Voltar à seleção", gridX, h - buttonH')
s=s[:a]+part+s[b:]
p.write_text(s,encoding='utf-8')
print('Landscape HUD and consumption footer revised')
